const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const caches=new Map();
const names={torch:'PyTorch / 参考',nvidia:'NVIDIA CUDA',amd:'AMD ROCm',ascend:'Ascend NPU'};
export async function computeMarkup(family,modelId,nodeId){
 if(!family.computePath)return '<h1>尚未收录逐层接口研究</h1>';
 if(!caches.has(family.computePath)){const r=await fetch(family.computePath);if(!r.ok)throw Error('逐层计算资料读取失败');caches.set(family.computePath,await r.json())}
 const d=caches.get(family.computePath),model=d.models.find(m=>m.id===modelId)||d.models.at(-1);
 return `<section id="compute-atlas" data-model="${esc(model.id)}" data-node="${esc(nodeId||'')}"><div class="page-head"><div class="eyebrow">LAYER COMPUTE / SOURCE SNAPSHOT ${d.snapshot}</div><h1>逐层计算与接口</h1><p class="intro">从真实层映射进入每一步计算，核对 shape、权重格式、参考 PyTorch 和设备后端。重复层共用模板，每层均可独立查看。</p></div><div class="stats"><div class="stat"><b>${d.counts.languageLayers}</b><span>语言层</span></div><div class="stat"><b>${d.counts.visionLayers}</b><span>视觉层</span></div><div class="stat"><b>${d.counts.steps.toLocaleString()}</b><span>逐层展开步骤</span></div><div class="stat"><b>${d.counts.proofs}</b><span>精确函数证据</span></div></div><div class="link-row">${d.downloads.map(f=>`<a class="button ${f.name.endsWith('.csv')?'primary':''}" href="${esc(f.path)}" download>${esc(f.name.includes('shapes.csv')?'计算流 / Shape 总表 CSV':f.name.includes('api-map.csv')?'后端接口总表 CSV':f.name.endsWith('.zip')?'按模型拆分 ZIP':f.name.endsWith('.json')?'完整 JSON':f.name.includes('说明')?'字段与符号说明':'详细 Markdown 报告')}</a>`).join('')}</div><details><summary>阅读前：证据、符号与实现边界</summary><ul>${d.notes.map(n=>`<li>${esc(n)}</li>`).join('')}</ul><dl class="research-pairs">${Object.entries(d.symbols).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl></details><div class="filters compute-filters"><label>版本<select id="compute-model">${d.models.map(m=>`<option value="${m.id}" ${m.id===model.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select></label><label>组件组<select id="compute-group"><option value="all">全部组件</option><option value="decoder">语言层</option><option value="vision">视觉层</option><option value="global">全局组件</option></select></label><label>层 / 组件<select id="compute-node"></select></label><label>后端<select id="compute-backend"><option value="all">全部接口</option>${Object.entries(names).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label>查找步骤 / shape / API<input id="compute-search" type="search" placeholder="KDA、q_b_proj、npu_grouped_matmul…"></label></div><div id="compute-model-info"></div><div id="compute-results" aria-live="polite"></div></section>`;
}
export function mountCompute(family){
 const root=document.querySelector('#compute-atlas');if(!root)return;
 const d=caches.get(family.computePath),$=id=>document.getElementById('compute-'+id);
 let model=d.models.find(m=>m.id===root.dataset.model),chosen=root.dataset.node||'all';
 function refs(ids){return `<details class="research-refs"><summary>函数来源（${new Set(ids).size}）</summary>${[...new Set(ids)].map(id=>{const p=d.proofs[id];return `<p><a target="_blank" rel="noopener" href="${esc(p.url)}">${esc(p.symbol)} ↗</a><small>${esc(p.repo)} @ ${esc(p.revision)}<br>${esc(p.path)} · L${p.line}–${p.end}<br>${esc(p.verification)}</small></p>`}).join('')}</details>`}
 function options(){const g=$('group').value;const ns=model.nodes.filter(n=>g==='all'||n.group===g||g==='global'&&!['decoder','vision'].includes(n.group));$('node').innerHTML='<option value="all">全部层（按模板折叠）</option>'+ns.map(n=>`<option value="${n.id}">${n.layer?(n.group==='vision'?'视觉 ':'语言 ')+n.layer:n.id} · ${n.type}${n.ffn?' / '+n.ffn:''}</option>`).join('');$('node').value=ns.some(n=>n.id===chosen)?chosen:'all';}
 function render(){const backend=$('backend').value,q=$('search').value.trim().toLowerCase(),g=$('group').value,nid=$('node').value;const ns=model.nodes.filter(n=>(g==='all'||n.group===g||g==='global'&&!['decoder','vision'].includes(n.group))&&(nid==='all'||n.id===nid));const groups=new Map();for(const n of ns){const key=n.template;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(n)}
 $('model-info').innerHTML=`<div class="notice"><a href="#/family/${family.id}/model/${model.id}">${esc(model.name)}：返回版本与3D结构 →</a><br>${Object.entries(model.symbols).map(([k,v])=>`${esc(k)}=${v}`).join(' · ')}<br>${model.id==='k2-base'?'Base使用同配置Instruct形状模板，非独立权重头审计。':'权重shape沿用固定检查点审计；服务端可能转置、分片或重新量化。'}</div>`;
 let total=0;const html=[...groups].map(([tid,nodes])=>{const t=d.templates[tid],steps=t.steps.filter(s=>!q||JSON.stringify(backend==='all'?s:{...s,apis:{[backend]:s.apis[backend]}}).toLowerCase().includes(q));if(!steps.length)return '';total+=steps.length;const label=nodes.length===1?(nodes[0].layer?`${nodes[0].group==='vision'?'视觉':'语言'}第 ${nodes[0].layer} 层` : nodes[0].id):`${nodes[0].group==='vision'?'视觉':'语言'} ${nodes.length} 层共用模板`;
 return `<section class="panel compute-template"><h2>${esc(label)} · ${esc(t.layerType)} / ${esc(t.ffn||'全局组件')}</h2><p class="small">${esc(tid)} · ${nodes[0].parameters.toLocaleString()} 逻辑参数/组件 · ${steps.length} 个匹配步骤</p><details><summary>完整层号映射（点击逐层查看）</summary><div class="compute-layer-links">${nodes.map(n=>`<a href="#/family/${family.id}/compute/${model.id}/${n.id}">${esc(n.layer||n.id)}</a>`).join('')}</div></details>${steps.map((s,i)=>`<details class="compute-step" ${nid!=='all'&&i===0?'open':''}><summary><span class="pill">${esc(s.id)}</span> ${esc(s.title)} <small>${esc(s.input)} → ${esc(s.output)}</small></summary><p>${esc(s.relation)}</p><dl class="research-pairs"><dt>输入</dt><dd>${esc(s.input)}</dd><dt>输出</dt><dd>${esc(s.output)}</dd><dt>中间 / 缓存</dt><dd>${esc(s.intermediate)}</dd><dt>阶段</dt><dd>${esc(s.phase)}</dd><dt>精度</dt><dd>${esc(s.dtype)}</dd></dl>${s.note?`<div class="notice">${esc(s.note)}</div>`:''}${s.tensors.length?`<div class="table-wrap"><table><thead><tr><th>权重 / 辅助张量</th><th>逻辑shape</th><th>存储shape / dtype</th><th>份数</th></tr></thead><tbody>${s.tensors.map(x=>`<tr><td>${esc(nodes.length===1?x.tensor_template.replace('{i}',nodes[0].layer-1):x.tensor_template)}</td><td>${esc(x.logical_shape)}</td><td>${esc(x.stored_shape)} / ${esc(x.stored_dtype)}</td><td>${x.multiplicity}</td></tr>`).join('')}</tbody></table></div>`:'<p class="small">本步骤没有新增权重；权重参数已在对应投影/归一化步骤计数。</p>'}<div class="api-cards">${Object.entries(s.apis).filter(([key])=>backend==='all'||backend===key).map(([key,a])=>`<article class="api-card"><h3>${names[key]}</h3><span class="small">${esc(a.level)} · ${esc(a.evidence)}</span><p class="api-chain">${esc(a.chain)}</p><p>${esc(a.condition)}</p>${a.proofs.length?refs(a.proofs):'<p class="small">未声称存在已核验设备API。</p>'}</article>`).join('')}</div>${refs(s.reference.proofs)}</details>`).join('')}</section>`}).join('');
 $('results').innerHTML=`<p class="count">${ns.length} 个组件 · ${total} 个模板步骤匹配（CSV完整展开每一层）</p>`+(html||'<div class="empty">没有匹配步骤，请调整关键词或组件范围。</div>');}
 $('model').onchange=()=>{model=d.models.find(m=>m.id===$('model').value);chosen='all';options();render()};$('group').onchange=()=>{chosen='all';options();render()};$('node').onchange=()=>{chosen=$('node').value;render()};$('backend').onchange=render;$('search').oninput=render;options();render();
}
